SELECT DATE_FORMAT(c.signup_date, 'yyyy-MM') AS signup_month, SUM(CASE WHEN t.merchant = 'Lazada' THEN t.amount ELSE 0 END) AS lazada_amount, MAX(t.amount) - MIN(t.amount) AS amount_range FROM transactions t INNER JOIN accounts a ON t.account_id = a.id INNER JOIN customers c ON a.customer_id = c.id WHERE c.is_active GROUP BY DATE_FORMAT(c.signup_date, 'yyyy-MM') ORDER BY lazada_amount DESC, signup_month LIMIT 3;
